    #[test]
    fn update_where_ignores_where_inside_multibyte_string() {
        let engine = NativeSqlEngine::new();
        engine
            .execute("CREATE TABLE upd_utf8 (id INTEGER PRIMARY KEY, text TEXT)")
            .unwrap();
        engine
            .execute("INSERT INTO upd_utf8 (id, text) VALUES (1, 'x'), (2, 'y')")
            .unwrap();
        // Latin-1 / CJK bytes inside the literal must not panic or redefine WHERE.
        engine
            .execute("UPDATE upd_utf8 SET text = 'café where 你好 [upd]' WHERE id = 1")
            .expect("multibyte SET value must not panic keyword scan");
        let r = engine
            .execute("SELECT text FROM upd_utf8 WHERE id = 1")
            .unwrap();
        assert_eq!(
            String::from_utf8_lossy(r.rows[0][0].as_ref().unwrap()),
            "café where 你好 [upd]"
        );
        let r2 = engine
            .execute("SELECT text FROM upd_utf8 WHERE id = 2")
            .unwrap();
        assert_eq!(
            String::from_utf8_lossy(r2.rows[0][0].as_ref().unwrap()),
            "y"
        );
    }

    #[test]
    fn update_where_ignores_where_inside_string_literal() {
        let engine = NativeSqlEngine::new();
        engine
            .execute("CREATE TABLE upd_quote (id INTEGER PRIMARY KEY, text TEXT)")
            .unwrap();
        engine
            .execute("INSERT INTO upd_quote (id, text) VALUES (1, 'hello'), (2, 'world')")
            .unwrap();
        // Chinese / English text may contain the word "where" — must not become a SET/WHERE split.
        engine
            .execute("UPDATE upd_quote SET text = 'go where you want [upd]' WHERE id = 1")
            .expect("quoted WHERE must not confuse parser");
        let r = engine
            .execute("SELECT text FROM upd_quote WHERE id = 1")
            .unwrap();
        assert_eq!(
            String::from_utf8_lossy(r.rows[0][0].as_ref().unwrap()),
            "go where you want [upd]"
        );
        let r2 = engine
            .execute("SELECT text FROM upd_quote WHERE id = 2")
            .unwrap();
        assert_eq!(
            String::from_utf8_lossy(r2.rows[0][0].as_ref().unwrap()),
            "world"
        );
    }

